<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/helpers.php';require_once __DIR__.'/../includes/password.php';requerirRol(['administrador']); requerirPermiso('departamentos.gestionar');
if(!verificarCsrf($_POST['csrf_token']??null)){header('Location: departamentos.php?error=csrf');exit;}
$n=trim($_POST['nombre']??'');$nombre=trim($_POST['nombre_persona']??'');$apellido=trim($_POST['apellido']??'');$cedula=strtoupper(trim($_POST['cedula']??''));$telefono=trim($_POST['telefono']??'');$correo=trim($_POST['correo']??'');$usuario=trim($_POST['usuario']??'');$pass=$_POST['password']??'';$confirm=$_POST['password_confirmation']??'';
if(!$n||!$nombre||!$apellido||!cedulaValida($cedula)||!telefonoValido($telefono)||!filter_var($correo,FILTER_VALIDATE_EMAIL)||!$usuario||!passwordValida($pass)||$pass!==$confirm){header('Location: departamentos.php?error=Datos+inválidos');exit;}
try{$pdo->beginTransaction();$q=$pdo->prepare("SELECT COUNT(*) FROM departamentos WHERE LOWER(TRIM(nombre))=LOWER(TRIM(?))");$q->execute([$n]);if($q->fetchColumn())throw new RuntimeException('Departamento duplicado');$role=$pdo->query("SELECT id_roles FROM roles WHERE nombre='departamento' LIMIT 1")->fetchColumn();if(!$role)throw new RuntimeException('Rol no disponible');$q=$pdo->prepare('SELECT COUNT(*) FROM usuarios WHERE usuario=?');$q->execute([$usuario]);if($q->fetchColumn())throw new RuntimeException('Usuario duplicado');$q=$pdo->prepare('SELECT COUNT(*) FROM perfiles_usuarios WHERE cedula=? OR correo=?');$q->execute([$cedula,$correo]);if($q->fetchColumn())throw new RuntimeException('Perfil duplicado');$pdo->prepare("INSERT INTO departamentos(nombre,estado) VALUES(?,'activo')")->execute([$n]);$dep=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO usuarios(usuario,contrasena,rol_id,estado) VALUES(?,?,?,'activo')")->execute([$usuario,password_hash($pass,PASSWORD_DEFAULT),$role]);$uid=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO perfiles_usuarios(usuario_id,nombre,apellido,cedula,correo,confirmar_correo,telefono,departamento_id) VALUES(?,?,?,?,?,1,?,?)')->execute([$uid,$nombre,$apellido,$cedula,$correo,$telefono,$dep]);$pdo->prepare('INSERT INTO auditoria_accesos(usuario_id,accion,detalle,ip) VALUES(?,?,?,?)')->execute([usuarioActual()['id'],'crear_departamento','Departamento '.$n.' y cuenta '.$usuario,$_SERVER['REMOTE_ADDR']??null]);$pdo->commit();header('Location: departamentos.php?ok=Departamento+creado');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();emitirLogError('No se pudo crear el departamento.',['code'=>$e->getCode()]);header('Location: departamentos.php?error=1');}exit;
